P1 and P2 are confirmed. Marginal gains: $+0.34$ to $+0.45$ for $k=1\to2$, $+0.12$ to $+0.17$ for $k=2\to4$, $+0.05$ to $+0.07$ for $k=4\to8$. The knee chain coincides exactly with that of an independent earlier sweep (different script, different session). Top-$24$ attention retains at least $0.98$ at every context.

\subsection{The Maslov-gap map}
Bulk layers have median gaps in $[0.17,1.86]$ nats at $n\in\{512,1024\}$, inside $\log 8\approx 2.08$; at $n=2048$ every bulk layer has median at most $1.46$. Layers 22 and 23 have medians $2.33/2.16$, $2.55/2.37$ and $2.69/2.52$ at the three contexts, with ninetieth percentile about $3.4$: the only far-from-tropical region.

\subsection{The crystallization map}
Per-layer mean crystallization lies in $[0.34,0.97]$; P3 is refuted.

\section{Gap equals min-entropy}

\begin{theorem}\label{thm:gap}
For every key $i$, $p_i=e^{-g_i}$.
\end{theorem}
\begin{proof}
With $Z=\sum_j e^{x_j}$, $e^{-g_i}=e^{x_i-\log Z}=e^{x_i}/Z=p_i$.
\end{proof}

\begin{corollary}
At an argmax $i$, an argmax cache keeps mass $M(\{i\})=e^{-g}$, and $g=-\log p_{\max}=H_\infty$.
\end{corollary}

A median gap of $1.86$ nats means the median row keeps only $e^{-1.86}\approx0.156$ of its mass on the top key; for the diffuse tail at $n=2048$, $e^{-2.69}\approx0.068$.

\section{The R\'enyi crystallization sandwich}

\begin{lemma}\label{lem:KC}
$K(x)=1-C(x)$.
\end{lemma}
\begin{proof}
$\sum_j p_j(1-p_j)=\sum_j p_j-\sum_j p_j^2$.
\end{proof}

\begin{theorem}\label{thm:coll}
If $i$ is an argmax with gap $g$, then $e^{-2g}\le C(x)\le e^{-g}$.
\end{theorem}
\begin{proof}
Upper: $C=\sum_j p_jp_j\le\sum_j p_jp_i=p_i=e^{-g}$. Lower: $C\ge p_i^2=e^{-2g}$.
\end{proof}

Equivalently $H_\infty\le H_2\le 2H_\infty$.

\begin{theorem}[Crystallization sandwich]
If $i$ is an argmax with gap $g$, then $1-e^{-g}\le K(x)\le 1-e^{-2g}$.
\end{theorem}
\begin{proof}
Lemma~\ref{lem:KC} and Theorem~\ref{thm:coll}.
\end{proof}

\begin{proposition}[Sharpness]
If $x$ is flat, then $K(x)=1-e^{-g}$.
\end{proposition}
\begin{proof}
All $p_j=p_i$, so $C=p_i=e^{-g}$.
\end{proof}

\begin{corollary}[Why P3 failed]\label{cor:p3}
If $g>1/3$ then $K(x)>1/4$. Conversely $K(x)\le1/4$ forces $g\le\log(4/3)\approx0.288$.
\end{corollary}
\begin{proof}
From $\log y\le y-1$, $\log(4/3)\le1/3<g$, so $e^{-g}<3/4$ and $K\ge1-e^{-g}>1/4$. Conversely, $K\le1/4$ gives $e^{-g}\ge 3/4$, i.e.\ $g\le\log(4/3)$.
\end{proof}

With bulk medians up to $1.86$ nats, more than five times $\log(4/3)$, the budget $1/4$ was incompatible with the gap map; the sandwich predicts crystallization at least $1-e^{-1.86}\approx0.84$ for such a row.

\section{Truncation in the log domain}

\begin{theorem}[Truncation identity]
For nonempty $S$, $\LSE(x)-\LSE_S(x)=-\log M(S)$. For $S=\{i\}$ at an argmax this equals $g$.
\end{theorem}
\begin{proof}
$M(S)=\sum_{j\in S}e^{x_j}/\sum_j e^{x_j}$; take logarithms; use Theorem~\ref{thm:gap}.
\end{proof}

\section{How many keys a retention target needs}

\begin{lemma}
If $i$ is an argmax, $M(S)\le|S|e^{-g}$ for every $S$.
\end{lemma}

\begin{theorem}[Gap floor]\label{thm:gapfloor}
If $M(S)\ge\tau$ then $|S|\ge\tau e^{g}$.
\end{theorem}

\begin{theorem}[Collision floor]\label{thm:collfloor}
$M(S)^2\le|S|\,C(x)$; hence if $0\le\tau\le M(S)$ then $|S|\ge\tau^2/C(x)=\tau^2/(1-K(x))$.
\end{theorem}
\begin{proof}
Cauchy--Schwarz: $(\sum_{j\in S}p_j)^2\le|S|\sum_{j\in S}p_j^2\le|S|C$; and $C\ge e^{-2g}>0$.
\end{proof}

\begin{theorem}[Knee floors]
Let $\tau$ be attainable for the profile $(p_i)$. (1) If $p_i\le q$ for all $i$, $q>0$, then $\kappa(\tau)\ge\tau/q$. (2) If $\tau\ge0$ and $\sum_{i<k}p_i^2\le C$ for all $k$, $C>0$, then $\kappa(\tau)\ge\tau^2/C$.
\end{theorem}
\begin{proof}
(1) $\tau\le R(\kappa)\le\kappa q$. (2) $\tau^2\le R(\kappa)^2\le\kappa\sum_{i<\kappa}p_i^2\le\kappa C$.
\end{proof}

\begin{corollary}[Gap calibration]
If every weight is at most $e^{-2.69}$, then $\kappa(0.98)\ge13$.
\end{corollary}
\begin{proof}
$\kappa\ge0.98e^{2.69}=0.98(e^{0.6725})^4$, and $e^{y}\ge1+y+y^2/2$ gives $e^{0.6725}\ge1.8986$, so $0.98\cdot1.8986^4>12$.
\end{proof}

\begin{remark}
Numerically $0.98e^{2.69}\approx14.4$, so the floor is in fact $15$.
\end{remark}

\begin{corollary}[Crystallization calibration]
If $\sum_{i<k}p_i^2\le0.03$ for all $k$, then $\kappa(0.98)\ge33$.
\end{corollary}
\begin{proof}
$0.98^2/0.03=32.01\ldots>32$.
\end{proof}

These floors bracket the measured knees $\{16,32,24\}$.

\section{Tropical core plus thin soft correction}

\begin{theorem}[Margin truncation bound]\label{thm:margin}
Let $S$ be nonempty, $|S|=k$, and $x_j+m\le x_s$ for all $j\notin S$, $s\in S$. Then $1-M(S)\le(n-k)e^{-m}/k$.
\end{theorem}
\begin{proof}
Let $A=\sum_{s\in S}e^{x_s}$, $B=\sum_{j\notin S}e^{x_j}$. For dropped $j$, $k e^{x_j}\le\sum_{s\in S}e^{-m}e^{x_s}=e^{-m}A$. Summing, $kB\le(n-k)e^{-m}A$, and $1-M(S)=B/(A+B)\le B/A$.
\end{proof}

A tail loss below $\delta$ is guaranteed once $m\ge\log\bigl((n-k)/(k\delta)\bigr)$: the required margin grows only logarithmically in the context.

\section{Why the argmax gets worse with context}

\begin{theorem}[Argmax floor]
If $x_i-x_j\ge m$ for every $j\ne i$, then $p_i\ge F(m,n)$.
\end{theorem}
\begin{proof}
$\sum_je^{x_j}\le e^{x_i}(1+(n-1)e^{-m})$.
\end{proof}

\begin{theorem}
For fixed $m$, $F(m,b)\le F(m,a)$ whenever $1\le a\le b$, and $F(m,n)\to0$ as $n\to\infty$.
\end{theorem}
\begin{proof}
The positive denominator is nondecreasing in $n$ and tends to $+\infty$.
\end{proof}

\section{The measured recovery is not a mass curve}\label{sec:notmass}

\begin{theorem}[Doubling inequality]
If $p_0\ge p_1\ge\cdots$, then $R(2k)\le2R(k)$.
\end{theorem}
\begin{proof}
$R(2k)=\sum_{i<k}p_i+\sum_{i<k}p_{k+i}$ and $p_{k+i}\le p_i$.
\end{proof}

\begin{theorem}[Retention is a nonlinear readout]
None of the measured pairs $(R(1),R(2))=(0.3637,0.7865)$, $(0.2885,0.7398)$, $(0.2503,0.7002)$ is realized by a sorted mass profile.
\end{theorem}
\begin{proof}
The ratios $2.16$, $2.56$, $2.80$ exceed $2$.
\end{proof}

\begin{theorem}[Weierstrass bounds]
For $\varepsilon_\ell\in[0,1]$,
\[
1-\sum_{\ell<L}\varepsilon_\ell\le\prod_{\ell<L}(1-\varepsilon_\ell)\le\exp\Bigl(-\sum_{\ell<L}\varepsilon_\ell\Bigr).
\]
\end{theorem}
\begin{proof}
Lower: induction using $(1-s)(1-\varepsilon)\ge1-s-\varepsilon$ for $s,\varepsilon\ge0$. Upper: $1-\varepsilon\le e^{-\varepsilon}$ termwise with nonnegative factors.
\end{proof}

\begin{corollary}[Compounded argmax budget]
If $\prod_\ell(1-\varepsilon_\ell)=0.2503$, then $0.7497\le\sum_\ell\varepsilon_\ell\le\log(1/0.2503)\approx1.385$.
\end{corollary}

\section{Algorithms}

\paragraph{A. Gap and crystallization map.} For each row: $\mu=\max_jx_j$, $\LSE=\mu+\log\sum_je^{x_j-\mu}$, $g=\LSE-\mu$, $p_j=e^{x_j-\LSE}$, $C=\sum p_j^2$, $K=1-C$; aggregate per layer. $O(n)$ per row.

\paragraph{B. Certified key floors.} Output $\max(\lceil\tau e^{g}\rceil,\lceil\tau^2/C\rceil)$ (Theorems~\ref{thm:gapfloor}--\ref{thm:collfloor}). $O(1)$ given A.

\paragraph{C. Margin certificate.} With $m=x_{(k)}-x_{(k+1)}$, output $(n-k)e^{-m}/k$ (Theorem~\ref{thm:margin}). The least $k$ whose certificate is below $\delta$ upper-bounds the per-row mass knee. $O(n\log n)$.

\section{Discussion}

The decay of pointer attention with context is the monotone decay of the argmax floor. The failure of P3 is forced by the gap map through the R\'enyi sandwich. The knee in the tens is forced by the gap and collision floors on the diffuse tail. Fast recovery reflects a tropical core plus a thin tail (Theorem~\ref{thm:margin}), while super-doubling shows that output quality depends nonlinearly on kept mass.

The deployable regime is a tropical core plus a thin soft correction: caches with $k\approx1$--$4$ are below the knee, but the measured curve prices every added key. Budgets should be layer-dependent, since only layers 22--23 have large gap floors.

\paragraph{Limitations.} One model, one corpus; oracle selection rather than a deployable policy; controls inherited, not rerun. The theorems concern kept mass; its link to measured retention is nonlinear and remains to be modeled.

\section{Future work}
\begin{enumerate}
\item \textbf{Layer-selective tropicalization:} top-$4$ caches where the median gap is at most $\log4$ and full caches in layers 22--23 should give retention at least $0.98$ at all contexts.
\item \textbf{Compounded readout law:} $R(k)\approx\prod_\ell m_\ell(k)$, so $-\log R(k)\approx\sum_\ell(1-m_\ell(k))$.
\item \textbf{Logarithmic margin law:} per-layer knee $\sim\log(n/\delta)/\bar m$.
\item \textbf{R\'enyi-2 eviction certificates:} per-head budget $\lceil\tau^2/\sum_ip_i^2\rceil$ within $1\%$ of oracle retention.
\item Size transfer, corpus robustness, and interaction with weight quantization.
\end{enumerate}

\section{Conclusion}
The tropical limit of attention is lossy and provably becomes lossier with context; the recovery is fast; and the needed cache size is governed exponentially by the Maslov gap $\LSE(x)-\max_jx_j$, which with the collision probability sandwiches the crystallization loss, certifies key floors, and locates the only far-from-tropical part of the model in its final two layers.

