"""Margin certificate for top-k truncation: lost mass <= (n-k) e^{-m} / k."""
from __future__ import annotations
import math
from typing import List, Optional, Sequence


def margin_certificate(x: Sequence[float], k: int) -> float:
    """Upper bound on the softmax mass dropped by keeping the k largest scores."""
    n = len(x)
    if k >= n:
        return 0.0
    s = sorted(x, reverse=True)
    m = s[k - 1] - s[k]                 # every dropped key is >= m below every kept key
    return (n - k) * math.exp(-m) / k


def certified_k(x: Sequence[float], delta: float) -> Optional[int]:
    """Smallest k whose certificate is <= delta (an upper bound on the mass knee at 1-delta)."""
    for k in range(1, len(x) + 1):
        if margin_certificate(x, k) <= delta:
            return k
    return None


def actual_loss(x: Sequence[float], k: int) -> float:
    mu = max(x)
    w = sorted((math.exp(v - mu) for v in x), reverse=True)
    return sum(w[k:]) / sum(w)


if __name__ == "__main__":
    import random
    rng = random.Random(2)
    x: List[float] = [14 + rng.gauss(0, .3) for _ in range(4)] + [rng.gauss(0, 1) for _ in range(2044)]
    for k in (1, 2, 4, 8):
        print(f"k={k}: actual loss {actual_loss(x, k):.4f} <= certificate {margin_certificate(x, k):.4f}")
    print("certified k for delta=0.02:", certified_k(x, 0.02))
